import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.LecternUpdate{Page: 200, PageCount: 255, Position: protocol.BlockPos{1, -2, 3}}
PAGE_COUNTERS_ABOVE_127 = bytes.fromhex("c8ff020306")

# generated by gophertunnel b8bd735:
# packet.LecternUpdate{Page: 0, PageCount: 1, Position: protocol.BlockPos{-1, 320, -300}}
WIDE_POSITION = bytes.fromhex("0001018005d704")

GOLDENS = [
    pytest.param(
        v2225.LecternUpdatePacket(page=200, total_pages=255, pos=v2225.BlockPos(x=1, y=-2, z=3)),
        PAGE_COUNTERS_ABOVE_127,
        id="page-counters-above-127",
    ),
    pytest.param(
        v2225.LecternUpdatePacket(page=0, total_pages=1, pos=v2225.BlockPos(x=-1, y=320, z=-300)),
        WIDE_POSITION,
        id="wide-position",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_lectern_update_is_packet_125(version):
    assert version.PACKETS[125] is version.LecternUpdatePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_lectern_update_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_lectern_update_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
